# ============================================================
# 06_sensitivity.R
# ============================================================
# Purpose:
#   Assess the sensitivity of country rankings generated by two
#   2-additive Choquet models under four orness scenarios.
#
# Inputs from previous project scripts:
#   vars       - criterion names
#   dimensions - matrix of criterion values, one row per country
#   data       - country-level data, optionally including Country
#   corr       - empirical correlation matrix
#   n          - number of criteria
#   orn_gm     - geometric-mean orness target
#
# Models:
#   1. ch_const - constant pairwise interactions
#   2. ch_corr  - correlation-based pairwise interactions
#
# Scenarios:
#   1. Minimum feasible orness
#   2. Geometric-mean orness
#   3. Midpoint interaction parameter (k = k*/2)
#   4. Arithmetic-mean orness (zero interactions)
#
# Main analyses:
#   1. Construction and validation of the four capacities.
#   2. Country scores and rankings for each model/scenario pair.
#   3. Kendall rank agreement across pairs of scenarios.
#   4. Number and magnitude of rank changes.
#   5. Distributions of absolute rank changes (two figures).
#
# Outputs:
#   - output/06a_sensitivity_orness/capacity_validity_summary.tex
#   - output/06a_sensitivity_orness/mid_orness_summary.tex
#   - output/06a_sensitivity_orness/scenario_rank_agreement.tex
#   - output/06a_sensitivity_orness/sensitivity_rank_changes_ch_const.pdf
#   - output/06a_sensitivity_orness/sensitivity_rank_changes_ch_corr.pdf
# ============================================================

# ------------------------------------------------------------
# DIRECTORY TO SAVE RESULTS AND NUMERICAL TOLERANCE
# ------------------------------------------------------------

out_dir <- "output/06a_sensitivity_orness"
tol <- 1e-8

# ------------------------------------------------------------
# DEFINE CRITERIA AND CAPACITY PARAMETERS
# ------------------------------------------------------------
# Equal Shapley importance is assumed for all three criteria.
# The vector phi is supplied by the upstream project scripts.
phi <- shap
phi_min <- min(phi)

# ------------------------------------------------------------
# DEFINE FUNCTIONS FOR CAPACITY CONSTRUCTION
# ------------------------------------------------------------
# Construct a symmetric interaction matrix from its three
# pairwise interaction coefficients.

interaction_matrix <- function(pair_values) {

  stopifnot(length(pair_values) == choose(n, 2))

  I <- matrix(
    0,
    nrow = n,
    ncol = n,
    dimnames = list(vars, vars)
  )

  I[upper.tri(I)] <- pair_values
  I[lower.tri(I)] <- t(I)[lower.tri(I)]

  I
}

# Calculate Mobius coefficients, orness, normalization, and
# monotonicity margins for a proposed 2-additive capacity.

validate_capacity <- function(I, scenario, model) {

  mob2 <- I[upper.tri(I)]
  mob1 <- phi - rowSums(I) / 2

  shapley <- mob1 + rowSums(I) / 2
  normalization <- sum(mob1) + sum(mob2)
  orness <- 0.5 - sum(mob2) / 3

  margins <- numeric(0)

  for (i in seq_len(n)) {

    others <- setdiff(seq_len(n), i)

    for (mask in 0:(2^length(others) - 1L)) {

      bits <- as.logical(
        intToBits(mask)[seq_along(others)]
      )

      chosen <- others[bits]

      interaction_sum <- if (length(chosen) > 0L) {
        sum(I[i, chosen])
      } else {
        0
      }

      margins <- c(
        margins,
        mob1[i] + interaction_sum
      )
    }
  }

  valid <- all(abs(shapley - phi) <= tol) &&
    abs(normalization - 1) <= tol &&
    all(margins >= -tol) &&
    all(mob1 >= -tol)

  list(
    model = model,
    scenario = scenario,
    interaction = I,
    mob1 = mob1,
    mob2 = mob2,
    shapley = shapley,
    normalization = normalization,
    orness = orness,
    min_monotonicity_margin = min(margins),
    valid = valid
  )
}

# Convert a validated set of Mobius coefficients into a kappalab
# capacity object for calculating Choquet integral scores.

make_capacity <- function(v) {

  if (!v$valid) {
    stop(
      "Invalid capacity for model ", v$model,
      ", scenario ", v$scenario, "."
    )
  }

  kappalab::Mobius.capacity(
    c(0, v$mob1, v$mob2, 0),
    n,
    n
  )
}

# ------------------------------------------------------------
# CONSTRUCT INTERACTION MATRICES FOR THE FOUR SCENARIOS
# ------------------------------------------------------------

# Dissimilarity is defined as one minus the empirical correlation.
D <- 1 - corr
diag(D) <- 0
D[D < 0 & D >= -tol] <- 0

if (any(D < -tol)) {
  stop("Invalid dissimilarity values derived from 'corr'.")
}

row_dissimilarity <- rowSums(D)

if (sum(D[upper.tri(D)]) <= tol) {
  stop("Correlation-based interactions cannot be constructed.")
}

if (any(row_dissimilarity <= tol)) {
  stop("At least one criterion has zero total dissimilarity.")
}

# Maximum feasible interaction parameters for the two models.

k1_star <- 2 * phi_min / (n - 1)
k2_star <- min(2 * phi / row_dissimilarity)

# midpoint parameter values.

k1_mid <- k1_star / 2
k2_mid <- k2_star / 2

# Minimum feasible orness.

I_const_min <- interaction_matrix(
  rep(k1_star, choose(n, 2))
)

I_corr_min <- k2_star * D

# mid-orness parameterization.

I_const_mid <- interaction_matrix(
  rep(k1_mid, choose(n, 2))
)

I_corr_mid <- k2_mid * D

# Geometric-mean orness target.

target_pair_sum <- n * (0.5 - orn_gm)
D_pairs <- D[upper.tri(D)]

I_const_geom <- interaction_matrix(
  rep(
    target_pair_sum / choose(n, 2),
    choose(n, 2)
  )
)

I_corr_geom <- interaction_matrix(
  target_pair_sum * D_pairs / sum(D_pairs)
)

# Arithmetic-mean orness: zero pairwise interactions.

I_zero <- interaction_matrix(
  rep(0, choose(n, 2))
)

# ------------------------------------------------------------
# DEFINE MODELS AND SCENARIOS
# ------------------------------------------------------------

interaction_sets <- list(

  ch_const = list(
    minimum_orness = I_const_min,
    geometric_mean_orness = I_const_geom,
    mid_orness_parameter = I_const_mid,
    arithmetic_mean_orness = I_zero
  ),

  ch_corr = list(
    minimum_orness = I_corr_min,
    geometric_mean_orness = I_corr_geom,
    mid_orness_parameter = I_corr_mid,
    arithmetic_mean_orness = I_zero
  )
)

# ------------------------------------------------------------
# DEFINE SCENARIO PROCESSING AND COMPARISON ORDER
# ------------------------------------------------------------
# This order determines the sequence of model/scenario calculations
# and the order of the six pairwise scenario comparisons and tables.

scenario_order <- c(
  "minimum_orness",
  "mid_orness_parameter",
  "geometric_mean_orness",
  "arithmetic_mean_orness"
)

# ------------------------------------------------------------
# CALCULATE ORNESS, VALIDATE CAPACITIES, AND RANK COUNTRIES
# ------------------------------------------------------------

# These objects are retained internally because the ranking
# comparisons depend on the scores from every model/scenario pair.

scenario_validations <- list()
score_columns <- list()
rank_columns <- list()
scenario_rows <- list()

for (model in names(interaction_sets)) {

  for (scenario in scenario_order) {

    I <- interaction_sets[[model]][[scenario]]
    key <- paste(model, scenario, sep = "__")

    v <- validate_capacity(I, scenario, model)
    scenario_validations[[key]] <- v

    if (!v$valid) {
      stop(
        "Capacity validation failed for ", model, " / ", scenario,
        ". Minimum monotonicity margin = ",
        v$min_monotonicity_margin
      )
    }

    cap <- make_capacity(v)

    scores <- apply(
      dimensions,
      1,
      function(x) {
        as.numeric(kappalab::Choquet.integral(cap, x))
      }
    )

    ranks <- rank(-scores, ties.method = "max")

    score_columns[[key]] <- scores
    rank_columns[[key]] <- ranks

    scenario_rows[[key]] <- data.frame(
      model = model,
      scenario = scenario,
      orness = v$orness,
      pairwise_mobius_sum = sum(v$mob2),
      normalization = v$normalization,
      min_monotonicity_margin = v$min_monotonicity_margin,
      valid = v$valid,
      stringsAsFactors = FALSE
    )
  }
}

capacity_summary <- do.call(rbind, scenario_rows)

print(
  xtable::xtable(capacity_summary, digits = 4),
  type = "latex",
  file = file.path(out_dir, "capacity_validity_summary.tex")
)

# ------------------------------------------------------------
# ORNESS TABLES
# ------------------------------------------------------------
# Table 1 reports orness under the midpoint parameter specification.
# Table 2 reports orness and capacity checks for all scenarios.
# ------------------------------------------------------------

mid_orness_table <- data.frame(
  model = c("ch_const", "ch_corr"),
  k_mid = c(k1_mid, k2_mid),
  orness = c(
    scenario_validations[["ch_const__mid_orness_parameter"]]$orness,
    scenario_validations[["ch_corr__mid_orness_parameter"]]$orness
  )
)

# ============================================================
# MANUSCRIPT OUTPUT: APPENDIX TABLE 11, ROWS 3 and 8
# ============================================================

orn_mid_ch_const <-mid_orness_table[1,3]
orn_mid_ch_corr <-mid_orness_table[2,3]

print(
  xtable::xtable(mid_orness_table, digits = 4),
  type = "latex",
  file = file.path(out_dir, "mid_orness_summary.tex")
)

# ------------------------------------------------------------
# PREPARE COUNTRY RANKINGS
# ------------------------------------------------------------

# Lower numerical rank indicates a higher position.
country_label <- if ("Country" %in% names(data)) {
  as.character(data$Country)
} else {
  paste0("row_", seq_len(nrow(dimensions)))
}

# ------------------------------------------------------------
# KENDALL AGREEMENT AND PAIRWISE RANK-CHANGE SUMMARY
# ------------------------------------------------------------
# For each model, compare all six pairs of orness scenarios.
# Kendall's tau measures rank agreement. The remaining statistics
# describe how many countries change rank and the magnitude of
# those movements.
# ------------------------------------------------------------

comparison_order <- c(
  "minimum_orness__mid_orness_parameter",
  "minimum_orness__geometric_mean_orness",
  "minimum_orness__arithmetic_mean_orness",
  "mid_orness_parameter__geometric_mean_orness",
  "mid_orness_parameter__arithmetic_mean_orness",
  "geometric_mean_orness__arithmetic_mean_orness"
)

tau_rows <- list()

movement_pair_rows <- list()

for (model in names(interaction_sets)) {

  for (i in seq_len(length(scenario_order) - 1L)) {

    for (j in seq.int(i + 1L, length(scenario_order))) {

      s1 <- scenario_order[i]
      s2 <- scenario_order[j]

      r1 <- rank_columns[[paste(model, s1, sep = "__")]]
      r2 <- rank_columns[[paste(model, s2, sep = "__")]]

      delta <- r2 - r1
      comparison_id <- paste(s1, s2, sep = "__")
      row_id <- paste(model, comparison_id, sep = "__")

      tau_rows[[row_id]] <- data.frame(
        model = model,
        scenario_1 = s1,
        scenario_2 = s2,

        kendall_tau = cor(
          r1, r2,
          method = "kendall",
          use = "complete.obs"
        ),

        n_changed = sum(delta != 0, na.rm = TRUE),
        percent_changed = 100 * mean(delta != 0, na.rm = TRUE),
        mean_absolute_rank_movement = mean(abs(delta), na.rm = TRUE),
        median_absolute_rank_movement = median(abs(delta),na.rm = TRUE),
        max_absolute_rank_movement = max(abs(delta), na.rm = TRUE),
        stringsAsFactors = FALSE
      )

      movement_pair_rows[[row_id]] <- data.frame(
        model = model,
        comparison = comparison_id,
        absolute_rank_change = abs(delta),
        stringsAsFactors = FALSE
      )
    }
  }
}

tau_summary <- do.call(rbind, tau_rows)

rank_changes <- do.call(rbind, movement_pair_rows)

# ============================================================
# MANUSCRIPT OUTPUT: APPENDIX TABLE 12
# ============================================================
# In Appendix Table 12, only columns 4–6 are retained.
# The omitted columns report additional information on ranking changes
# across pairs of orness scenarios. These results provide a further
# check of the numerical similarity in Kendall's tau between the two
# Choquet models for the pairwise comparison of orness scenarios
# (s_{mid}) and (s_A). Although Kendall's tau values coincide, the number
# of countries changing rank and the mean and maximum absolute rank movements
# differ between the two models.

print(
  xtable::xtable(tau_summary, digits = 4),
  type = "latex",
  file = file.path(out_dir, "scenario_rank_agreement.tex")
)

# ------------------------------------------------------------
# FIGURE LABELS AND MODEL DISPLAY ORDER
# ------------------------------------------------------------
# Stable scenario/model identifiers are retained in the analysis
# data. Mathematical notation is introduced only for figure display.
scenario_labels <- c(
  minimum_orness = "s[min]",
  mid_orness_parameter = "s[mid]",
  geometric_mean_orness = "s[G]",
  arithmetic_mean_orness = "s[A]"
)

model_labels <- c(
  ch_const = "C[mu[1]]",
  ch_corr = "C[mu[2]]"
)

comparison_labels <- vapply(
  comparison_order,
  function(pair) {

    parts <- strsplit(
      pair,
      "__",
      fixed = TRUE
    )[[1]]

    label1 <- unname(scenario_labels[parts[1]])
    label2 <- unname(scenario_labels[parts[2]])

    paste0(
      label1,
      " * ' - ' * ",
      label2
    )
  },
  character(1)
)

names(comparison_labels) <- comparison_order

rank_changes$model <- factor(
  rank_changes$model,
  levels = names(model_labels)
)

rank_changes$comparison <- factor(
  rank_changes$comparison,
  levels = comparison_order
)
# ------------------------------------------------------------
# JOURNAL FIGURE THEME
# ------------------------------------------------------------

theme_journal <- function() {
  theme_minimal(base_size = 9) +
    theme(
      panel.grid.major = element_line(linewidth = 0.2),
      panel.grid.minor = element_blank(),
      axis.text = element_text(color = "black", size = 8),
      axis.title = element_text(size = 9),
      strip.text = element_text(size = 8),
      panel.spacing.y = grid::unit(1.5, "lines"),
      panel.spacing.x = grid::unit(1.2, "lines"),
      legend.position = "none"
    )
}

# ------------------------------------------------------------
# SENSITIVITY FIGURES: ONE FIGURE PER CHOQUET MODEL
# ------------------------------------------------------------
# Each figure contains:
#   Panel A - distributions of absolute rank changes
#   Panel B - boxplots of absolute rank changes
#
# All six scenario pairs are shown using the same mathematical
# labels and journal theme for consistency across models.
# ------------------------------------------------------------

make_sensitivity_figure <- function(model_name) {

  if (!model_name %in% names(model_labels)) {
    stop("Unknown model name: ", model_name)
  }

  model_data <- rank_changes[
    rank_changes$model == model_name,
    ,
    drop = FALSE
  ]

  if (nrow(model_data) == 0L) {
    stop("No data found for model: ", model_name)
  }

  # Histogram panel
  p_hist <- ggplot(
    model_data,
    aes(x = absolute_rank_change)
  ) +
    geom_histogram(
      binwidth = 1,
      boundary = -0.5,
      fill = "grey75",
      colour = "black",
      linewidth = 0.25
    ) +
    facet_wrap(
      ~ comparison,
      ncol = 2,
      drop = FALSE,
      labeller = labeller(
        comparison = as_labeller(
          comparison_labels,
          default = label_parsed
        )
      )
    ) +
    scale_y_sqrt() +
    scale_x_continuous(
      breaks = scales::pretty_breaks(n = 4)
    ) +
    labs(
      x = "Absolute rank change",
      y = "Frequency"
    ) +
    theme_journal()

  # Horizontal boxplot panel
  p_box <- ggplot(
    model_data,
    aes(
      x = absolute_rank_change,
      y = comparison
    )
  ) +
    geom_boxplot(
      fill = "grey75",
      colour = "black",
      linewidth = 0.35,
      width = 0.6,
      outlier.size = 0.7
    ) +
    scale_y_discrete(
      limits = rev,
      labels = function(x) {
        parse(
          text = unname(
            comparison_labels[as.character(x)]
          )
        )
      },
      drop = FALSE
    ) +
    scale_x_continuous(
      breaks = scales::pretty_breaks(n = 6)
    ) +
    labs(
      x = "Absolute rank change",
      y = NULL
    ) +
    theme_journal()

  # Return plots and title together
  if (model_name == "ch_const") {
    model_title <- expression(C[mu[1]])
  } else if (model_name == "ch_corr") {
    model_title <- expression(C[mu[2]])
  } else {
    model_title <- model_name
  }

  return(
    list(
      hist = p_hist,
      box = p_box,
      title = model_title
    )
  )
}

# ------------------------------------------------------------
# Plots for both models
# ------------------------------------------------------------

plots_const <- make_sensitivity_figure("ch_const")
plots_corr  <- make_sensitivity_figure("ch_corr")

# ------------------------------------------------------------
# MANUSCRIPT OUTPUT: APPENDIX FIGURE 4
# ------------------------------------------------------------

fig_const <- (
  plots_const$hist | plots_const$box
) +
  plot_layout(widths = c(2, 1)) +
  plot_annotation(title = plots_const$title)

fig_corr <- (
  plots_corr$hist | plots_corr$box
) +
  plot_layout(widths = c(2, 1)) +
  plot_annotation(title = plots_corr$title)

ggsave(
  file.path(out_dir, "sensitivity_rank_changes_ch_const.pdf"),
  plot = fig_const,
  width = 7,
  height = 8
)

message("Sensitivity analysis of orness completed.")
